INSERT INTO school_uniforms (school_number, uniform_type, slacks_skirt_choice, quote, source) VALUES
  ('401010', '制服なし（服装自由）', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 制服 制服はありません。', 'https://www.metro.ed.jp/hitotsubashi-hc/our_school/symbols.html'),
  ('401020', '制服あり（形は公式サイト参照）', 1, '気候に応じて上着なし、学校指定のセーター・ベスト、グレー色のスラックス・スカートも可とする。', 'https://www.metro.ed.jp/hibiya-h/school_life/symbols.html'),
  ('401040', 'ブレザー', 1, '制服について（生徒手帳より抜粋） １．登校下校時及び校内では必ず制服を着用し、着こなしは清楚、端正を旨とし三田高生として品位を保つ。', 'https://www.metro.ed.jp/mita-h/school_life/symbols.html'),
  ('401210', '制服あり（形は公式サイト参照）', 1, '冬服と夏服、スカートの代わりにスラックス、リボンの代わりにネクタイも選べます オプションとして、指定のセーターとベストがあります 夏服にポロシャツが導入されました。', 'https://www.metro.ed.jp/osaki-h/school_life/symbols.html'),
  ('401240', '学ラン', 0, '制服のスタイルは、男子は黒の詰襟、女子は紺のブレーザーにリボンです。', 'https://www.metro.ed.jp/yukigaya-h/school_life/symbols.html'),
  ('401250', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/omori-h/school_life/symbols.html'),
  ('401290', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/kamata-h/school_life/symbols.html'),
  ('401410', '制服あり（形は公式サイト参照）', 0, '夏服 左から、女子ズボン（オプション）・女子スカート・男子 冬服 左から、男子・女子・ポロシャツ（男女兼用）。', 'https://www.metro.ed.jp/tsubasasogo-h/school_life/symbols.html'),
  ('401420', '標準服', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 標準服 標準服の購入・着用は自由です。', 'https://www.metro.ed.jp/roppongi-he/our_school/symbols.html'),
  ('401520', '制服あり（形は公式サイト参照）', 0, '男女、夏服・冬服ともに英国調の落ち着いたさわやかなデザインです。', 'https://www.metro.ed.jp/mihara-h/school_life/symbols.html'),
  ('401620', '制服あり（形は公式サイト参照）', 0, '夏服 冬服 制服ＰＤＦ。', 'https://www.metro.ed.jp/otasakuradai-h/school_life/symbols.html'),
  ('402010', '制服なし（服装自由）', 0, '本校は制服がありません。', 'https://www.metro.ed.jp/toyama-h/school_life/symbols.html'),
  ('402030', '標準服（制服なし）', 0, '本校には標準服があります。', 'https://www.metro.ed.jp/komaba-h/school_life/symbols.html'),
  ('402040', 'ブレザー', 0, '・校則 制服・校章・校歌・校則 制服 冬服は落ち着いたブレザータイプです。', 'https://www.metro.ed.jp/meguro-h/school_life/symbols.html'),
  ('402210', '制服あり（形は公式サイト参照）', 0, '男子はネクタイ着用。', 'https://www.metro.ed.jp/matsubara-h/school_life/symbols.html'),
  ('402220', '標準服', 1, '本校は標準服ではなく、制服です。', 'https://www.metro.ed.jp/sakuramachi-h/school_life/symbols.html'),
  ('402250', '制服あり（形は公式サイト参照）', 1, 'シャツは⻘⾊と⽩⾊があります。', 'https://www.metro.ed.jp/chitosegaoka-h/school_life/symbols.html'),
  ('402410', 'ブレザー', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 制服 紺の上着にグレー×ブルーのボトムを合わせた明るく爽やかな２つボタンブレザータイプで、生徒は自由な校則に合わせて着こなしています。', 'https://www.metro.ed.jp/setagayaizumi-he/our_school/symbols.html'),
  ('402420', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/setagayasogo-h/school_life/symbols.html'),
  ('402520', '制服なし（服装自由）', 0, '制服はありません。', 'https://www.metro.ed.jp/shinjukuyamabuki-h/school_life/symbols.html'),
  ('402530', '制服あり（形は公式サイト参照）', 0, '冬服の紹介 世界中で愛されるブリティッシュスタイルで、ベーシックなモデルです。', 'https://www.metro.ed.jp/roka-h/school_life/symbols.html'),
  ('402620', 'ブレザー', 0, '冬服 男子は、ブレザー・スラックス・白ワイシャツ・ネクタイ・ソックスについては紺色または黒色の無地ソックス・黒の革靴。', 'https://www.metro.ed.jp/daiichishogyo-h/school_life/symbols.html'),
  ('402750', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/sogokoka-h/school_life/symbols.html'),
  ('402810', '制服あり（形は公式サイト参照）', 0, '創立100周年を記念し、新たな時代に見合ったデザインとしてチェック柄を中心とした制服としました。', 'https://www.metro.ed.jp/engei-h/school_life/symbols.html'),
  ('403010', '制服あり（形は公式サイト参照）', 0, '・校旗 制服・校章・校歌・校旗 夏服 冬服。', 'https://www.metro.ed.jp/saginomiya-h/school_life/symbols.html'),
  ('403020', '学ラン・セーラー', 1, NULL, 'https://www.metro.ed.jp/fuji-s/school_life/symbols.html'),
  ('403030', '標準服', 0, '標準服は武蔵丘の誇り 入学式をはじめとする式典や、来校者を迎える行事の際には、全校生徒が標準服を着用します。', 'https://www.metro.ed.jp/musashigaoka-h/school_life/symbols.html'),
  ('403040', '標準服（制服なし）', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 制服 本校に制服はありません。', 'https://www.metro.ed.jp/ogikubo-he/our_school/symbols.html'),
  ('403050', '制服なし（服装自由）', 0, '本校は制服はございません。', 'https://www.metro.ed.jp/nishi-h/school_life/symbols.html'),
  ('403060', '制服なし（服装自由）', 0, '豊多摩高校には制服はありません。', 'https://www.metro.ed.jp/toyotama-h/school_life/symbols.html'),
  ('403070', '学ラン・セーラー', 0, '昭和28年の創立以来の伝統ある制服で、男子は詰入型（学ランタイプ）、女子はセーラー服です。', 'https://www.metro.ed.jp/suginami-h/school_life/symbols.html'),
  ('403210', '標準服', 0, '石神井高校では、平成２５年度入学生より、現在の標準服を制服として着用を義務付け、あわせて頭髪を染めたり、脱色等を禁止します。', 'https://www.metro.ed.jp/shakujii-h/school_life/symbols.html'),
  ('403220', '制服あり（形は公式サイト参照）', 0, '制服については学校運営方針・校則内に記載してありますのでそちらをご確認ください。', 'https://www.metro.ed.jp/igusa-h/school_life/symbols.html'),
  ('403230', '制服あり（形は公式サイト参照）', 0, '夏服中学 冬服中学 夏服高校 冬服高校 制服紹介動画： https://www.youtube.com/watch?v=tzSLRPSQmG8。', 'https://www.metro.ed.jp/oizumi-h/school_life/symbols.html'),
  ('403240', 'ブレザー', 1, '制服は、所定のブレザーに男子はズボン＋ベルト、女子はスカートまたはスラックスがあります。', 'https://www.metro.ed.jp/nerima-h/school_life/symbols.html'),
  ('403250', 'ブレザー', 0, '平成21年入学者から新しいものになりました 男子 紺のブレザー・グレーのズボン。', 'https://www.metro.ed.jp/hikarigaoka-h/school_life/symbols.html'),
  ('403280', '制服あり（形は公式サイト参照）', 1, '令和２年度（第４０期）入学生より、制服を一新しました。', 'https://www.metro.ed.jp/tagara-h/school_life/symbols.html'),
  ('403410', 'ブレザー', 0, '服装は次の本校指定の制服を着用すること。', 'https://www.metro.ed.jp/suginamisogo-h/school_life/symbols.html'),
  ('403420', '制服あり（形は公式サイト参照）', 0, '本校では、学校生活全般にわたり、学校指定の「校服」を着用します。', 'https://www.metro.ed.jp/minorigaoka-he/school_life/symbols.html'),
  ('403510', 'ブレザー', 1, '選べる制服 生徒にも人気の制服は、冬服はチャコールグレーのブレザー・スラックス・スカートです。', 'https://www.metro.ed.jp/oizumisakura-h/school_life/symbols.html'),
  ('403720', 'ブレザー', 1, '令和６年度 制服リニューアル ブレザー、ボトムズ、ネクタイ、夏用ボトムズがあります。', 'https://www.metro.ed.jp/suginamikoka-h/school_life/symbols.html'),
  ('403730', 'ブレザー', 1, '制服は本校指定のものを購入、着用します。', 'https://www.metro.ed.jp/nerimakoka-h/school_life/symbols.html'),
  ('403810', '制服あり（形は公式サイト参照）', 0, '上下とも家庭で洗濯できる素材で出来ています。', 'https://www.metro.ed.jp/nogei-h/school_life/symbols.html'),
  ('404010', '学ラン・セーラー', 0, '標準服（購入・着用任意） 男子は詰襟学生服、女子はセーラー服の標準服がありますが、購入・着用ともに任意です。', 'https://www.metro.ed.jp/takehaya-h/school_life/symbols.html'),
  ('404020', '制服あり（形は公式サイト参照）', 0, '本校には指定の制服（冬服と夏服）があります。', 'https://www.metro.ed.jp/mukogaoka-h/school_life/symbols.html'),
  ('404040', 'ブレザー', 1, '令和2年度入学生より制服デザイン一新!! スクールカラーのえんじ色を取り入れました。', 'https://www.metro.ed.jp/toshima-h/school_life/symbols.html'),
  ('404050', 'ブレザー', 0, NULL, 'https://www.metro.ed.jp/bunkyo-h/school_life/symbols.html'),
  ('404210', '制服なし（服装自由）', 0, '本校は制服がありません。', 'https://www.metro.ed.jp/kitazono-h/school_life/symbols.html'),
  ('404260', 'ブレザー', 1, '高島高校の制服です。', 'https://www.metro.ed.jp/takashima-h/school_life/symbols.html'),
  ('404510', 'ブレザー', 1, '・校章・生徒心得・校歌 制服・校章・生徒心得・校歌 制服 紺のブレザータイプの制服です。', 'https://www.metro.ed.jp/asuka-h/school_life/symbols.html'),
  ('404520', 'セーラー', 1, 'クラシックなタイプの制服です。', 'https://www.metro.ed.jp/itabashiyutoku-h/school_life/symbols.html'),
  ('404640', '標準服', 0, '本校の制服は標準服ではなく、登下校および校内では着用することになっています。', 'https://www.metro.ed.jp/chihaya-h/school_life/symbols.html'),
  ('404730', '制服あり（形は公式サイト参照）', 0, '令和6年度生まで 令和7年度生から新制服。', 'https://www.metro.ed.jp/kitatoshimakoka-h/school_life/symbols.html'),
  ('404910', 'ブレザー', 0, '【POINT1】全アイテム 気品と清潔感があり洗練されたデザイン 濃紺をベースとし、スーツに近いフォーマルで、いつでも誰からも信頼される印象を与える制服です。', 'https://www.metro.ed.jp/akabanehokuo-h/school_life/symbols.html'),
  ('405040', '学ラン', 1, '本校では、府立第一高等女学校の時代(大正14年頃)に東京下町でシンボル的存在となったボレロ型上着と、昭和24年に男女共学となった際に導入された男子の詰め襟型の制服を長らく愛用し続けてきました。', 'https://www.metro.ed.jp/hakuo-h/school_life/symbols.html'),
  ('405050', 'ブレザー', 1, '平成18年に新たに採用された制服は、日本人として初めてパリコレクションにモデルとして参加された故山口小夜子さんにデザインを依頼して制作された。', 'https://www.metro.ed.jp/shinobugaoka-h/school_life/symbols.html'),
  ('405060', '制服あり（形は公式サイト参照）', 0, '伝統ある上野高校に相応しい、格調高く品のあるデザイン 冬服 冬服は男女とも濃紺のジャケットです。', 'https://www.metro.ed.jp/ueno-h/school_life/symbols.html'),
  ('405070', 'ブレザー', 0, '--> 制服 生徒会の意見を取り入れた、機能的で快適な制服です。', 'https://www.metro.ed.jp/takenodai-h/school_life/symbols.html'),
  ('405210', 'ブレザー', 0, '夏服 令和2年度よりポロシャツを導入しました。', 'https://www.metro.ed.jp/adachi-h/school_life/symbols.html'),
  ('405220', '制服あり（形は公式サイト参照）', 0, '新制服（平成29年度入学生から） 平成29年度入学生から、シャドーストライプのスーツスタイルの新制服となりました。', 'https://www.metro.ed.jp/kohoku-h/school_life/symbols.html'),
  ('405230', 'ブレザー', 0, '人気の高かった2代目制服をもとに、現代的なデザインと仕様を採用しました。', 'https://www.metro.ed.jp/fuchie-h/school_life/symbols.html'),
  ('405240', 'ブレザー', 0, 'ブレザー、スラックスまたはスカート 白シャツ、白ブラウス、白ポロシャツ（夏期） ネクタイまたはリボン ニットベスト（白・指定）、セーター（グレー・指定） 校章「五色桜」の由来 本校の校章は、日本の国花として、清純さを象徴する桜であり、遠くから見ると五色にたなびく霞のように見える「五色桜」を象徴化したものである。', 'https://www.metro.ed.jp/adachinishi-h/school_life/symbols.html'),
  ('405250', '制服あり（形は公式サイト参照）', 0, '・校則 制服・校章・校歌・校則 制服。', 'https://www.metro.ed.jp/adachihigashi-h/school_life/symbols.html'),
  ('405260', '制服あり（形は公式サイト参照）', 0, '夏服 冬服 ・女子はスラックスも選択もできます。', 'https://www.metro.ed.jp/aoi-h/school_life/symbols.html'),
  ('405270', '制服あり（形は公式サイト参照）', 0, '選べる制服 男子の制服 女子の制服 ・女子はスラックスも選択できます。', 'https://www.metro.ed.jp/adachishinden-h/school_life/symbols.html'),
  ('405410', 'セーラー', 0, '制服のデザイン 冬服のボタンには、6つの系列を表す、船の舵輪があしらわれています。', 'https://www.metro.ed.jp/harumisogo-h/school_life/symbols.html'),
  ('405520', '標準服', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 制服 本校は「標準服」です。', 'https://www.metro.ed.jp/asakusa-he/our_school/symbols.html'),
  ('405710', 'ブレザー', 1, '2019年度入学生より、新制服となります。', 'https://www.metro.ed.jp/kuramaekoka-h/school_life/symbols.html'),
  ('405730', 'ブレザー', 0, '平成29年度入学生より、今までのモスグリーンを基調とした制服から、チャコールグレーのブレザーとチェックのスラックス又はスカートにシルバーのタイをあしらったデザインに変更となりました。', 'https://www.metro.ed.jp/adachikoka-h/school_life/symbols.html'),
  ('406010', '制服あり（形は公式サイト参照）', 0, '附属中学 希望する女子はスラックスも購入できます 高校 希望する女子はスラックスも購入できます。', 'https://www.metro.ed.jp/ryogoku-h/school_life/symbols.html'),
  ('406020', 'ブレザー', 1, '男子は伝統の学ラン。', 'https://www.metro.ed.jp/sumidagawa-h/school_life/symbols.html'),
  ('406030', 'ブレザー', 0, '冬服 夏服 ポロシャツ コンセプト 落ち着いた校風にマッチしたデザイン。', 'https://www.metro.ed.jp/honjo-h/school_life/symbols.html'),
  ('406040', 'ブレザー', 0, '「伝統と新生」をテーマにした濃紺のシングル3つボタンブレザースタイルです。', 'https://www.metro.ed.jp/katsushikano-h/school_life/symbols.html'),
  ('406050', 'ブレザー', 1, '冬服 青を基調と新しいエンブレムが、胸元のワンポイントになっています。', 'https://www.metro.ed.jp/minamikatsushika-h/school_life/symbols.html'),
  ('406070', 'ブレザー', 0, '本校指定の制服 冬季 男子 指定のブレザー、ズボン、ネクタイ、白色無地のワイシャツ 女子 指定のブレザー、スカート、リボン、白色無地のワイシャツ、ブラウス 夏季 ６月～９月は男子の学生服上着、女子のブレザーは着用しなくてもよい。', 'https://www.metro.ed.jp/nihonbashi-h/school_life/symbols.html'),
  ('406210', '制服あり（形は公式サイト参照）', 0, '平成１６年度より、現在のデザインになりました。', 'https://www.metro.ed.jp/fukagawa-h/school_life/symbols.html'),
  ('406220', 'ブレザー', 0, '令和７年度より制服を変更 本校では、校則の自己点検や見直しを生徒や保護者と協力して実施しています。', 'https://www.metro.ed.jp/higashi-h/school_life/symbols.html'),
  ('406240', '制服あり（形は公式サイト参照）', 0, '夏服 冬服 校章・キャラクター。', 'https://www.metro.ed.jp/komatsugawa-h/school_life/symbols.html'),
  ('406250', '標準服（制服なし）', 0, '「標準服」 本校では、始業式、終業式、入学式、卒業式などの儀式、中間・期末考査や実力テストなどの考査時、学年集会や講演会などで「標準服」を着用します。', 'https://www.metro.ed.jp/edogawa-h/school_life/symbols.html'),
  ('406260', '標準服', 0, '制服は、当初は標準服として、保護者・生徒代表を加えた選定会議で原案を作り、平成17年9月の文化祭で中学生など約500名に投票していただき決定したものです。', 'https://www.metro.ed.jp/koiwa-h/school_life/symbols.html'),
  ('406270', 'ブレザー', 1, '夏服 白のワイシャツまたはポロシャツのいずれかを選べます。', 'https://www.metro.ed.jp/kasaiminami-h/school_life/symbols.html'),
  ('406280', 'ブレザー', 0, NULL, 'https://www.metro.ed.jp/shinozaki-h/school_life/symbols.html'),
  ('406290', 'ブレザー', 0, '夏服 夏は白のワイシャツのほか、白のポロシャツの着用も認められています。', 'https://www.metro.ed.jp/momijigawa-h/school_life/symbols.html'),
  ('406410', '制服あり（形は公式サイト参照）', 0, '落ち着いた深みのあるチャコールグレーの生地（夏・冬服とも） リボン・ネクタイは、エンジベース（女子は両方着用可） 女子のジャケットは、プリンセスラインをとり、美しいシルエット。', 'https://www.metro.ed.jp/oedo-he/school_life/symbols.html'),
  ('406420', '学ラン・セーラー', 0, 'デザインの特徴は トラディショナル（伝統）の中にも新しさと若々しさを感じさせる本校のオリジナルデザインです。', 'https://www.metro.ed.jp/katsushikasogo-h/school_life/symbols.html'),
  ('406720', '制服あり（形は公式サイト参照）', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 校則 特に校則はありません。', 'https://www.metro.ed.jp/honjokoka-he/our_school/symbols.html'),
  ('406730', '制服あり（形は公式サイト参照）', 1, '服装は質素，端正，清潔にし，通学に際しては図に示す本校指定の学生服を着用する。', 'https://www.metro.ed.jp/sumidakoka-h/school_life/symbols.html'),
  ('406910', 'ブレザー', 0, '本校の制服は、それが入学の決め手になる生徒も多い人気のデザインです。', 'https://www.metro.ed.jp/tachibana-h/school_life/symbols.html'),
  ('407020', 'ブレザー', 1, '【冬服】 男子：紺の縞柄入り詰め襟学生服上下、シャツ 女子：紺のブレザー、グレンチェックのプリーツスカート、シャツ 【夏服】 男子：グレーのスラックス、襟付シャツ 女子：グレンチェックのプリーツスカート、襟付シャツ ※女子はネクタイ・リボン自由、スラックス選択可。', 'https://www.metro.ed.jp/fujimori-h/school_life/symbols.html'),
  ('407030', 'ブレザー', 0, '制服は紺のブレザーにグレーのスラックス・スカートという ベーシックなデザインになっており、誰でも着こなすことができます。', 'https://www.metro.ed.jp/katakura-h/school_life/symbols.html'),
  ('407040', 'ブレザー', 0, '全体の濃茶のイメージはそのままに、素材やデザインに現代的で品位ある要素を取り入れました。', 'https://www.metro.ed.jp/hachiojihigashi-h/school_life/symbols.html'),
  ('407050', '制服あり（形は公式サイト参照）', 0, '学校指定の制服を着用すること。', 'https://www.metro.ed.jp/hachiojikita-h/school_life/symbols.html'),
  ('407070', 'ブレザー', 0, '夏服 スラックス・スカートは本校指定のものとする。', 'https://www.metro.ed.jp/matsugaya-h/school_life/symbols.html'),
  ('407080', '制服あり（形は公式サイト参照）', 0, '日野高校は、創立50周年を迎えました。', 'https://www.metro.ed.jp/hino-h/school_life/symbols.html'),
  ('407090', 'ブレザー', 0, '平成19年度に開校以来4半世紀を経過した制服を、魅力ある学校作りの観点から改定しました。', 'https://www.metro.ed.jp/hinodai-h/school_life/symbols.html'),
  ('407100', 'ブレザー', 0, '男子 ブレザー・ズボン、ネクタイ(共に指定のもの)、白無地ワイシャツ 女子 ブレザー・スカート(紺色)、ズボン、ネクタイ、リボンタイ(共に指定のもの)、白無地ワイシャツ ①夏服 a.男女とも、ブレザー、ネクタイ・リボンタイを着用しなくてもよい。', 'https://www.metro.ed.jp/minamidaira-h/school_life/symbols.html'),
  ('407210', '制服なし（服装自由）', 0, '--> 制服 制服はありません。', 'https://www.metro.ed.jp/machida-h/school_life/symbols.html'),
  ('407230', '制服あり（形は公式サイト参照）', 0, '夏服はポロシャツOK 女子用のスラックスもあります。', 'https://www.metro.ed.jp/nozuta-h/school_life/symbols.html'),
  ('407250', 'ブレザー', 1, '・生徒手帳 制服・校章・校歌・生徒手帳 制服 夏服 夏季制服 6月1日から9月30日までとする。', 'https://www.metro.ed.jp/ogawa-h/school_life/symbols.html'),
  ('407260', '制服あり（形は公式サイト参照）', 0, '※夏季・冬季の期間を定めた夏服・冬服の指定はありません。', 'https://www.metro.ed.jp/yamasaki-h/school_life/symbols.html');
INSERT INTO school_uniforms (school_number, uniform_type, slacks_skirt_choice, quote, source) VALUES
  ('407420', '制服あり（形は公式サイト参照）', 0, '本校の制服は、カッティング、縫製の良さに加えて、上品な光沢、滑らかな手触りのウールサキソニー生地を採用しています。', 'https://www.metro.ed.jp/machidasogo-h/school_life/symbols.html'),
  ('407510', 'ブレザー', 1, '夏服 夏服はワイシャツまたはポロシャツに、指定のズボンかスカートが選択できます。', 'https://www.metro.ed.jp/shoyo-h/school_life/symbols.html'),
  ('407520', '標準服（制服なし）', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 標準服 本校は私服登校を許可しています。', 'https://www.metro.ed.jp/hachiojitakushin-he/our_school/symbols.html'),
  ('407720', '制服あり（形は公式サイト参照）', 0, '春夏服 秋冬服 実習服。', 'https://www.metro.ed.jp/machidakoka-h/school_life/symbols.html'),
  ('408010', '制服なし（服装自由）', 0, '都立立川高等学校には、制服はありません。', 'https://www.metro.ed.jp/tachikawa-h/school_life/symbols.html'),
  ('408030', '制服なし（服装自由）', 0, '通信制課程の制服はありません。', 'https://www.metro.ed.jp/sunagawa-hc/school_life/symbols.html'),
  ('408040', '標準服（制服なし）', 0, '標準服紹介 昭和高校には、制服はありません。', 'https://www.metro.ed.jp/showa-h/school_life/symbols.html'),
  ('408050', 'ブレザー', 1, '服装や身だしなみは、その人の人格、教養を端的に示すものであるといわれる。', 'https://www.metro.ed.jp/haijima-h/school_life/symbols.html'),
  ('408060', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/higashiyamato-h/school_life/symbols.html'),
  ('408070', 'ブレザー', 0, '2020年度に大幅リニューアルしました。', 'https://www.metro.ed.jp/musashimurayama-h/school_life/symbols.html'),
  ('408210', 'ブレザー', 0, '制服は、本校の卒業生である花井幸子氏が多摩高生のためにデザインしています。', 'https://www.metro.ed.jp/tama-h/school_life/symbols.html'),
  ('408230', 'ブレザー', 1, '福生高校の制服は、写真のようにオリジナルの２ボタンのブレザーの上着に、男子はダークグレーのスラックスと青いネクタイ、女子はピンクのラインが入ったチェック柄のスカートに、ネクタイまたはリボンが正装です。', 'https://www.metro.ed.jp/fussa-h/school_life/symbols.html'),
  ('408240', '制服あり（形は公式サイト参照）', 0, 'ゆるぎない生活指導で、すがすがしい毎日を保証します 本校の生活指導は、自らの判断と責任で行動できる生徒の育成を目標としています。', 'https://www.metro.ed.jp/akirudai-h/school_life/symbols.html'),
  ('408250', 'ブレザー', 0, '【新制服】 羽村高校の服装に関する規定は以下の通りです。', 'https://www.metro.ed.jp/hamura-h/school_life/symbols.html'),
  ('408420', 'ブレザー', 0, '制服は、男女ともに濃紺のブレザーに、男子はダークグレーのスラックスとワイシャツ、ネクタイ、女子は紺のチェック柄のスカートに、ワイシャツ、ネクタイかリボンとなります。', 'https://www.metro.ed.jp/omesogo-h/school_life/symbols.html'),
  ('408430', '標準服（制服なし）', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 制服 ※標準服・制服はありません。', 'https://www.metro.ed.jp/tachikawamidori-he/our_school/symbols.html'),
  ('408510', 'ブレザー', 1, '--> 制服 生徒にも大変人気の校服。', 'https://www.metro.ed.jp/josui-h/school_life/symbols.html'),
  ('408820', '制服あり（形は公式サイト参照）', 0, '女子の制服は、紺色を基調にした、大き目のフリーツで、落ちつきのあるタータンチェック柄が入っています。', 'https://www.metro.ed.jp/mizuhonogei-h/school_life/symbols.html'),
  ('409010', 'ブレザー', 0, '制服（校服）は武蔵高等学校・附属中学校の集団全体を表わすと共に、同じ学校で学ぶ者の連帯のしるしです。', 'https://www.metro.ed.jp/musashi-h/school_life/symbols.html'),
  ('409020', 'ブレザー', 1, '武蔵野北高校の制服は、「この制服を着たかったからムサキタを選んだ。', 'https://www.metro.ed.jp/musashinokita-h/school_life/symbols.html'),
  ('409030', '制服あり（形は公式サイト参照）', 0, '夏はワイシャツの他にポロシャツ（学校指定）を着用することができます。', 'https://www.metro.ed.jp/koganeikita-h/school_life/symbols.html'),
  ('409040', '制服あり（形は公式サイト参照）', 0, '平成26年度から新しい制服に変わりました ウォッシャブル素材やストレッチ裏地を使用し、着やすさ快適さを備えた、上品でシックな制服です。', 'https://www.metro.ed.jp/hoya-h/school_life/symbols.html'),
  ('409060', '制服あり（形は公式サイト参照）', 0, '※注記：冬服のみ、女子生徒用スラックスもあります。', 'https://www.metro.ed.jp/kurumenishi-h/school_life/symbols.html'),
  ('409070', 'ブレザー', 0, '制服のコンセプト 緑の多い環境の中で生徒と教職員の信頼関係の下に生徒の個性と能力を伸ばす規律ある進学校 女子の制服ポイント 女子はリボンを採用し、可愛らしさを演出します。', 'https://www.metro.ed.jp/tanashi-h/school_life/symbols.html'),
  ('409210', '制服あり（形は公式サイト参照）', 0, '夏服 夏服では、略装として無地の白ポロシャツを着てもよいことになっています。', 'https://www.metro.ed.jp/kodaira-h/school_life/symbols.html'),
  ('409220', 'ブレザー', 0, '標準服（女子ネクタイver） ブレザーの紺と下はグレーの組み合わせです 標準服（女子リボンver） 夏服（ネクタイ有） グレーストライプ柄とネイビーチェック柄から選べます 白ポロシャツも可 夏服（ノーネクタイ） 女子スラックス ポロシャツ。', 'https://www.metro.ed.jp/kodairanishi-h/school_life/symbols.html'),
  ('409230', '制服あり（形は公式サイト参照）', 0, '校章 本校は昭和43(1968)年４月に、「東村山市にぜひ都立高校を」という地元の要望がかなって開設されました。', 'https://www.metro.ed.jp/higashimurayama-h/school_life/symbols.html'),
  ('409240', 'ブレザー', 0, '本校には指定の制服（ブレザー、スラックス、スカート）があります。', 'https://www.metro.ed.jp/kokubunji-h/school_life/symbols.html'),
  ('409250', 'ブレザー', 1, '令和7年度入学生から、制服が新しくなりました。', 'https://www.metro.ed.jp/kiyose-h/school_life/symbols.html'),
  ('409270', '制服あり（形は公式サイト参照）', 0, 'セーター・ベスト：それぞれ紺・グレーの2色あります。', 'https://www.metro.ed.jp/kodairaminami-h/school_life/symbols.html'),
  ('409280', 'ブレザー', 0, 'ブレザーとネクタイ スカート 上衣 ブレザー（チャコールグレー) ネクタイ マーク刺しゅう入り 男子 スラックス 女子 スカートまたはスラックス ※希望により学校指定のカーディガン、ベストあり （夏服） ワイシャツまたは開襟シャツ(白無地) 男子 夏用スラックス 女子 夏用スカートまたはスラックス。', 'https://www.metro.ed.jp/higashimurayamanishi-h/school_life/symbols.html'),
  ('409410', '制服あり（形は公式サイト参照）', 1, '濃いチャコールグレーを基調とした３つボタンのジャケットに、ストライプ柄のスカートやスラックスを組み合わせたデザインの制服です。', 'https://www.metro.ed.jp/higashikurumesogo-h/school_life/symbols.html'),
  ('409710', '制服なし（服装自由）', 0, '・施設・沿革 制服・校章・校歌・施設・沿革 制服 当校には制服はありません。', 'https://www.metro.ed.jp/koganeikoka-he/our_school/symbols.html'),
  ('409720', 'ブレザー', 0, '夏の服装 男子 ①白のワイシャツ （白無地のポロシャツ） ②学校指定のズボン 女子 ①白のブラウス （白無地のポロシャツ） ②学校指定のスカート、ズボン ・女子は本校指定のベスト等を可とします。', 'https://www.metro.ed.jp/tanashikoka-h/school_life/symbols.html'),
  ('409730', '制服あり（形は公式サイト参照）', 1, '本校の制服は、社会人のスーツを意識したデザインで落ち着いた雰囲気に仕立ててあります。', 'https://www.metro.ed.jp/tamakagakugijutsu-h/school_life/symbols.html'),
  ('410020', 'ブレザー', 0, '本校には「制服」はありません。', 'https://www.metro.ed.jp/jindai-h/school_life/symbols.html'),
  ('410030', 'セーラー', 0, '平成25年度から制服が新しくなりました。', 'https://www.metro.ed.jp/chofukita-h/school_life/symbols.html'),
  ('410040', 'ブレザー', 1, '本校の制服は、本校指定ブレザー、ズボン、スカートを基本にしたスタイルで、夏服の購入は希望購入になっています。', 'https://www.metro.ed.jp/chofuminami-h/school_life/symbols.html'),
  ('410050', 'ブレザー', 0, '夏季はブレザー及びワイシャツの場合はネクタイ・リボンを着用しないことも可能です。', 'https://www.metro.ed.jp/komae-h/school_life/symbols.html'),
  ('410210', '標準服', 0, NULL, 'https://www.metro.ed.jp/fuchu-h/school_life/symbols.html'),
  ('410220', 'ブレザー', 0, '本校には制服があります。', 'https://www.metro.ed.jp/fuchuhigashi-h/school_life/symbols.html'),
  ('410230', 'ブレザー', 1, '紺・臙脂（えんじ）・ブルーを基調とし、伝統を引き継いだデザインです。', 'https://www.metro.ed.jp/fuchunishi-h/school_life/symbols.html'),
  ('410240', '制服なし（服装自由）', 0, '当校には制服はありません。', 'https://www.metro.ed.jp/kunitachi-h/school_life/symbols.html'),
  ('410250', 'ブレザー', 1, '校の服装に関する規定は、次のとおりです。', 'https://www.metro.ed.jp/nagayama-h/school_life/symbols.html'),
  ('410410', 'ブレザー', 1, '総合学科は社会との接点も多いため、落ち着いて清潔感のある制服を採用しています。', 'https://www.metro.ed.jp/wakabasogo-h/school_life/symbols.html'),
  ('410710', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/fuchukoka-h/school_life/symbols.html'),
  ('410810', '制服あり（形は公式サイト参照）', 0, '実習服 向かって左から、食物科、緑地計画科、都市園芸科、食品科学科の実習服です。', 'https://www.metro.ed.jp/nogyo-h/school_life/symbols.html'),
  ('411010', '制服あり（形は公式サイト参照）', 0, NULL, 'https://www.metro.ed.jp/oshima-h/school_life/symbols.html'),
